{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cod_orders_limit as WITH order_summary AS ( SELECT order_name, webshopney, checkout, order_status, order_timestamp::date as date, discount_code, tags, sum(is_refund) as total_is_refund, SUM(gross_sales) AS total_gross_sales, SUM(quantity) AS total_quantity, sum(shipping_price) as total_shipping_price, sum(ifnull(slashed_discount,0)) as total_slashed_discount, sum(ifnull(coupon_discount,0)) as total_coupon_discount, sum(ifnull(discount,0)) as total_discount FROM snitch_db.maplemonk.fact_items_snitch where lower(payment_channel) = \'cod\' AND lower(order_status) != \'cancelled\' and lower(ifnull(discount_code,\'n\')) not like \'%eco%\' and lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and tags not in (\'FLITS_LOGICERP\') GROUP BY 1,2,3,4,5,6,7 ) SELECT * FROM order_summary WHERE ((webshopney = \'Web\' AND total_gross_sales > 1600) OR (webshopney IN (\'Shopney\', \'Appbrew\') AND total_gross_sales > 2100) OR (webshopney = \'Snitch_IOS\' AND tags LIKE \'%Snitch_IOS%\' AND total_gross_sales > 2600) OR (webshopney = \'Snitch_IOS\' AND tags LIKE \'%Snitch_Android%\' AND total_gross_sales > 2600)) ORDER BY date DESC ; CREATE OR REPLACE TABLE snitch_db.maplemonk.datewise_high_discount_low_value AS ( SELECT order_name, order_timestamp::date AS date, discount_code, sum(quantity) as quantity, sum(slashed_discount) as slashed_discount, sum(case when lower(discount_code) like \'%rms%\' then 0 else discount end) as discount, sum(coupon_discount) as coupon_discount, sum(free_gift_discount) as free_gift_discount, sum(loyalty_discount) as loyalty_discount, SUM(gross_sales) AS gross_sales, div0(SUM(case when lower(discount_code) like \'%rms%\' then 0 else discount end), SUM((case when lower(discount_code) like \'%rms%\' then 0 else discount end) + gross_sales)) * 100 AS discount_percentage from snitch_db.maplemonk.fact_items_snitch WHERE lower(ifnull(discount_code,\'n\')) not like \'%eco%\' and lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and order_name not in (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') and tags not in (\'FLITS_LOGICERP\') and lower(order_status) != \'cancelled\' GROUP BY order_name, date, discount_code );",
                    "transaction": true
                }
            ) }}
